package com.trombokendu.chronos.analytics;import java.time.*;import java.util.*;public record ForecastRequest(double currentBalance,LocalDate start,int horizon,int paths,Map<DayOfWeek,Double> dailyMeans,long seed){public ForecastRequest{dailyMeans=Map.copyOf(dailyMeans);if(horizon<1||paths<1)throw new IllegalArgumentException();}public static Builder builder(){return new Builder();}public static final class Builder{double balance;LocalDate start=LocalDate.now();int horizon=90,paths=20000;Map<DayOfWeek,Double> means=new EnumMap<>(DayOfWeek.class);long seed=42;public Builder balance(double x){balance=x;return this;}public Builder start(LocalDate x){start=x;return this;}public Builder horizon(int x){horizon=x;return this;}public Builder paths(int x){paths=x;return this;}public Builder dailyMean(DayOfWeek d,double x){means.put(d,x);return this;}public Builder seed(long x){seed=x;return this;}public ForecastRequest build(){return new ForecastRequest(balance,start,horizon,paths,means,seed);}}}
